import { useAppContext } from "@providers/AppContext";
import { useTheme } from "@providers/ThemeProvider";
import SideBarSmall from "./sidebar-small";
import SideBarExpanded from "./sidebar-expanded";

const { sidebarExpanded } = useAppContext();


export default function SideBar() {
    return (
        <aside
            className="shrink-0 transition-all duration-750 ease-in-out max-[910px]:bg-bg-secondary max-[910px]:absolute max-[910px]:w-full max-[910px]:min-w-[380px]"
            style={{
                width: sidebarExpanded ? "260px" : "60px",
            }}
        >
            <div
                className="relative h-full transition-all duration-750 ease-in-out overflow-hidden z-[100] bg-bg-secondary"
                style={{
                    width: sidebarExpanded ? "260px" : "60px",
                    opacity: sidebarExpanded ? 1 : 0,
                }}
            >
                <SideBarExpanded />
            </div>
            <div
                className="max-w-[60px] h-full overflow-hidden absolute"
                style={{ left: 0, top: 0 }}
            >
                <SideBarSmall />
            </div>
        </aside>
    );
}