import Sidebar from "@components/layout/sidebar";

export default function ChatLayout({
    children,
}: {
    children: React.ReactNode;
}) {

    return <div className="flex h-full w-full bg-bg text-text-secondary">
        <div className="shrink-0 transition-all duration-750 ease-in-out max-[910px]:bg-bg-secondary max-[910px]:absolute max-[910px]:w-full max-[910px]:min-w-[380px]">
            <Sidebar />
        </div>
        <section className="flex flex-col h-full transition-all duration-750 ease-in-out 
        border-l border-solid border-gray-dark">
            {children}
        </section>
    </div>;
}